// Display interpreter (REQ-3)
// Turns a 24 x 40 page of raw bytes into a 24 x 40 grid of display cells,
// following the Level 1 spacing attribute rules in docs/ets300706-level1-reference.md.
//
// A first version of this file was generated by Kiro (kept in
// docs/review-notes/). It was rewritten by hand after review found that it
// misread "bit 6" of the G1 mosaic set, took the lower row of a double-height
// pair from the wrong row, and lost the held mosaic on Release Mosaics.

import type { RawPage, Size, CharMode, Colour } from './types.js';
import { COLS, ROWS, PROMPT_ROW, getCell } from './grid.js';
import { decodeBlockMask } from './mosaic.js';

export interface DisplayCell {
  /** One visible character, or ' ' when the cell shows no text. */
  char: string;
  /** Foreground colour index 0 to 7. */
  fg: Colour;
  /** Background colour index 0 to 7. */
  bg: Colour;
  /** True while Flash is in force for this cell. */
  flash: boolean;
  /** True when this cell is concealed and reveal is off. */
  conceal: boolean;
  size: Size;
  charMode: CharMode;
  /** 6-bit block mask (TL=1, TR=2, ML=4, MR=8, LL=16, LR=32), only for mosaic cells. */
  mosaicMask: number;
  separated: boolean;
}

interface State {
  fg: Colour;
  bg: Colour;
  flash: boolean;
  conceal: boolean;
  double: boolean;
  mosaic: boolean;
  separated: boolean;
  hold: boolean;
  held: number | null;
  heldSeparated: boolean;
}

function rowDefaults(): State {
  return {
    fg: 7,
    bg: 0,
    flash: false,
    conceal: false,
    double: false,
    mosaic: false,
    separated: false,
    hold: false,
    held: null,
    heldSeparated: false,
  };
}

const SET_AT = new Set([0x09, 0x0c, 0x18, 0x19, 0x1a, 0x1c, 0x1d, 0x1e]);
const NO_EFFECT = new Set([0x00, 0x0e, 0x0f, 0x10]);

function isColourCode(b: number): boolean {
  return (b >= 0x01 && b <= 0x07) || (b >= 0x11 && b <= 0x17);
}

/** Apply a control byte to the state. */
function apply(b: number, s: State, row: number): void {
  if (isColourCode(b)) {
    const mosaic = b >= 0x11;
    if (mosaic !== s.mosaic) s.held = null;
    s.mosaic = mosaic;
    s.fg = (mosaic ? b - 0x10 : b) as Colour;
    s.conceal = false;
    return;
  }
  switch (b) {
    case 0x08:
      s.flash = true;
      return;
    case 0x09:
      s.flash = false;
      return;
    case 0x0c:
      if (s.double) s.held = null;
      s.double = false;
      return;
    case 0x0d:
      if (row === PROMPT_ROW) return;
      if (!s.double) s.held = null;
      s.double = true;
      return;
    case 0x18:
      s.conceal = true;
      return;
    case 0x19:
      s.separated = false;
      return;
    case 0x1a:
      s.separated = true;
      return;
    case 0x1c:
      s.bg = 0;
      return;
    case 0x1d:
      s.bg = s.fg;
      return;
    case 0x1e:
      s.hold = true;
      return;
    case 0x1f:
      s.hold = false;
      return;
    default:
      // 0x0A End Box, 0x0B Start Box and 0x1B ESC change nothing that is shown.
      return;
  }
}

function glyphForAlpha(b: number): string {
  return b === 0x7f ? '\u25a0' : String.fromCharCode(b);
}

function emitPrintable(b: number, s: State, reveal: boolean): DisplayCell {
  const hidden = s.conceal && !reveal;
  let char = ' ';
  let charMode: CharMode = 'alpha';
  let mask = 0;
  if (s.mosaic && (b & 0x20) !== 0) {
    // G1 mosaic: bit 6 (0x20) is set for 0x20-0x3F and 0x60-0x7F.
    charMode = 'mosaic';
    mask = decodeBlockMask(b);
    s.held = b;
    s.heldSeparated = s.separated;
  } else {
    char = glyphForAlpha(b);
  }
  if (hidden) {
    char = ' ';
    mask = 0;
    charMode = 'alpha';
  }
  return {
    char,
    fg: s.fg,
    bg: s.bg,
    flash: s.flash,
    conceal: hidden,
    size: s.double ? 'double-height-top' : 'normal',
    charMode,
    mosaicMask: mask,
    separated: charMode === 'mosaic' ? s.separated : false,
  };
}

function controlCell(s: State, reveal: boolean): DisplayCell {
  const hidden = s.conceal && !reveal;
  const showHeld = s.hold && s.held !== null && !hidden;
  return {
    char: ' ',
    fg: s.fg,
    bg: s.bg,
    flash: s.flash,
    conceal: hidden,
    size: s.double ? 'double-height-top' : 'normal',
    charMode: showHeld ? 'mosaic' : 'alpha',
    mosaicMask: showHeld ? decodeBlockMask(s.held as number) : 0,
    separated: showHeld ? s.heldSeparated : false,
  };
}

function emitControl(b: number, s: State, reveal: boolean, row: number): DisplayCell {
  if (SET_AT.has(b)) {
    // Set-at: the code changes the state before its own cell is drawn.
    apply(b, s, row);
    return controlCell(s, reveal);
  }
  // Set-after: the cell is drawn with the state in force before the code.
  const cell = controlCell(s, reveal);
  apply(b, s, row);
  return cell;
}

function lowerRowCell(upper: DisplayCell): DisplayCell {
  return {
    char: ' ',
    fg: upper.fg,
    bg: upper.bg,
    flash: false,
    conceal: false,
    size: upper.size === 'double-height-top' ? 'double-height-lower' : 'normal',
    charMode: 'alpha',
    mosaicMask: 0,
    separated: false,
  };
}

/**
 * Interpret a whole page.
 * @param reveal when true, concealed text is shown instead of hidden.
 */
export function interpretPage(page: RawPage, reveal = false): DisplayCell[][] {
  const grid: DisplayCell[][] = [];
  let previousHadDouble = false;

  for (let row = 0; row < ROWS; row++) {
    if (previousHadDouble) {
      // The row below a double-height row shows only the background of the
      // cells above it. Its own transmitted data is ignored.
      const upper = grid[row - 1] as DisplayCell[];
      grid.push(upper.map(lowerRowCell));
      previousHadDouble = false;
      continue;
    }

    const s = rowDefaults();
    const cells: DisplayCell[] = [];
    let rowHasDouble = false;
    for (let col = 0; col < COLS; col++) {
      const b = getCell(page, row, col);
      if (b >= 0x20) {
        cells.push(emitPrintable(b, s, reveal));
      } else if (NO_EFFECT.has(b)) {
        // Not interpreted at Level 1: behaves exactly like a space.
        cells.push(emitPrintable(0x20, s, reveal));
      } else {
        if (b === 0x0d && row !== PROMPT_ROW) rowHasDouble = true;
        cells.push(emitControl(b, s, reveal, row));
      }
    }
    grid.push(cells);
    previousHadDouble = rowHasDouble;
  }
  return grid;
}
